import copy

def transform(grid):
    H = len(grid)
    W = len(grid[0])

    # Identify background color (most frequent)
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    bg = max(counts, key=counts.get)

    # Build a set of non-background pixel positions
    non_bg = set()
    pixel_values = {}

    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val != bg:
                non_bg.add((r, c))
                pixel_values[(r, c)] = val

    # Create output grid
    out = [[bg] * W for _ in range(H)]

    # For each non-background pixel, place its value in all 4 symmetric positions
    for (r, c), val in pixel_values.items():
        out[r][c] = val  # original
        out[H-1-r][c] = val  # vertical mirror
        out[r][W-1-c] = val  # horizontal mirror
        out[H-1-r][W-1-c] = val  # point reflection

    return out
